create table if not exists public.inventory_refusals ( id uuid primary key default gen_random_uuid(), bucket text not null, rows_asked integer not null, refused_at timestamptz not null default timezone('utc', now()) );
create index if not exists inventory_refusals_when_idx on public.inventory_refusals (refused_at desc);
alter table public.inventory_refusals enable row level security;
do $$ begin create policy "Admins read refusals" on public.inventory_refusals for select using (public.is_admin()); exception when duplicate_object then null; end; $$;
comment on table public.inventory_refusals is 'One row each time spend_inventory_budget refused a read. Internal: it says which customer asked for too much and when. Admin policy only, no customer-facing policy.';
create or replace function public.spend_inventory_budget( p_bucket text, p_rows integer, p_max integer, p_window_seconds integer ) returns integer language plpgsql security definer set search_path = public as $$ declare v_now timestamptz := timezone('utc', now()); v_cost integer := greatest(0, coalesce(p_rows, 0)); v_count integer; v_expires timestamptz; begin insert into public.rate_limits (bucket, count, expires_at) values (p_bucket, v_cost, v_now + make_interval(secs => p_window_seconds)) on conflict (bucket) do update set count = case when public.rate_limits.expires_at <= v_now then v_cost else public.rate_limits.count + v_cost end, expires_at = case when public.rate_limits.expires_at <= v_now then v_now + make_interval(secs => p_window_seconds) else public.rate_limits.expires_at end returning count, expires_at into v_count, v_expires; if v_count > p_max then insert into public.inventory_refusals (bucket, rows_asked) values (p_bucket, v_cost); return greatest(1, ceil(extract(epoch from (v_expires - v_now)))::integer); end if; return 0; end; $$;
comment on function public.spend_inventory_budget(text, integer, integer, integer) is 'Spend a number of inventory rows against an account''s hourly budget. Returns 0 when the read may proceed, or the seconds until the window resets, recording the refusal in inventory_refusals. Shares the rate_limits table with consume_rate_limit; the unit is rows rather than attempts.';
revoke all on function public.spend_inventory_budget(text, integer, integer, integer) from public, anon, authenticated;
grant execute on function public.spend_inventory_budget(text, integer, integer, integer) to service_role;
